/** 判题脚手架：类型声明与白名单（"后端说它是 Trip"，但边界才是事实）。 */
export interface TripStop {
  readonly name: string;
  readonly arrival?: string;
}

export interface Trip {
  readonly id: string;
  readonly stops: TripStop[];
  readonly budgetCents: number;
  readonly timezone: string;
}

export interface Issue {
  readonly path: string;
  readonly message: string;
}

export type Parsed<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly issues: Issue[] };

export const TIMEZONES: readonly string[] = ['Asia/Shanghai', 'America/Los_Angeles', 'Europe/Dublin', 'UTC'];

import { fireEvent, render, screen } from '@testing-library/react';
import { expect, it } from 'vitest';
import { TripList, parseTrip } from './Solution';

const GOOD = {
  id: '9007199254740993',
  stops: [{ name: 'PVG', arrival: '2026-03-08T09:15:00' }, { name: 'SFO' }],
  budgetCents: 129900,
  timezone: 'Asia/Shanghai',
  vendorInternalCode: 'ignore-me',
};

const issuesOf = (res) => (!res.ok ? res.issues.map((issue) => issue.path) : []);

it('合法 payload 还原全部字段并忽略未知字段', () => {
  const res = parseTrip(GOOD);
  expect(res.ok).toBe(true);
  if (res.ok) {
    expect(res.value.id).toBe('9007199254740993');
    expect(res.value.stops.length).toBe(2);
    expect(res.value.stops[1].arrival).toBeUndefined();
    expect(res.value.budgetCents).toBe(129900);
    expect(res.value.timezone).toBe('Asia/Shanghai');
    expect(Object.prototype.hasOwnProperty.call(res.value, 'vendorInternalCode')).toBe(false);
  }
});

it('空 stops 数组是合法结果不是错误', () => {
  const res = parseTrip({ ...GOOD, stops: [] });
  expect(res.ok).toBe(true);
  if (res.ok) expect(res.value.stops.length).toBe(0);
});

it('数字 id 判为契约错误而不是自动转字符串', () => {
  const res = parseTrip({ ...GOOD, id: 42 });
  expect(res.ok).toBe(false);
  expect(issuesOf(res)).toEqual(['id']);
  expect(res.issues[0].message.length).toBeGreaterThan(0);
});

it('数组空洞与显式 undefined 逐项定位 path', () => {
  const holes = [null, { name: 'PVG' }, { name: '   ' }, { name: 'SFO', arrival: undefined }, { name: 'LHR', arrival: '3月8日' }];
  holes[5] = { name: 'NRT' };
  const res = parseTrip({ ...GOOD, stops: holes });
  expect(res.ok).toBe(false);
  expect(issuesOf(res)).toEqual(['stops[0]', 'stops[2].name', 'stops[3].arrival', 'stops[4].arrival']);
});

it('超大 500 项 stops 全量校验且 issue 按索引升序', () => {
  const stops = Array.from({ length: 500 }, (_unused, i) => (i % 100 === 5 ? { name: 123 } : { name: 'S' + i }));
  const res = parseTrip({ ...GOOD, stops });
  expect(res.ok).toBe(false);
  expect(issuesOf(res)).toEqual(['stops[5].name', 'stops[105].name', 'stops[205].name', 'stops[305].name', 'stops[405].name']);
});

it('非法输入只返回 issue 绝不抛异常', () => {
  const junk = [null, undefined, 'text', [], 0, { id: 'a' }, { ...GOOD, budgetCents: Number.NaN }, { ...GOOD, budgetCents: -1 }, { ...GOOD, timezone: 'Mars/Valles' }];
  const crashes: string[] = [];
  for (const item of junk) {
    try {
      const res = parseTrip(item);
      if (res.ok) crashes.push('accepted:' + JSON.stringify(item));
    } catch (error) {
      crashes.push('threw:' + String(error));
    }
  }
  expect(crashes).toEqual([]);
  const missing = parseTrip({ ...GOOD, id: 'a' });
  expect(issuesOf(missing)).toEqual(['id']);
  const budget = parseTrip({ ...GOOD, budgetCents: 12.5 });
  expect(issuesOf(budget)).toEqual(['budgetCents']);
  const zone = parseTrip({ ...GOOD, timezone: 'Mars/Valles' });
  expect(issuesOf(zone)).toEqual(['timezone']);
});

it('TripList 坏行只降级该行并显示 issue 路径', () => {
  const raws = [GOOD, { ...GOOD, id: 7, timezone: 'Mars/Valles' }, { ...GOOD, id: 'x2' }];
  render(<TripList raws={raws} />);
  expect(screen.getByTestId('trip-9007199254740993').textContent).toBe('2 站 · Asia/Shanghai');
  expect(screen.getByTestId('invalid-1').textContent).toBe('id,timezone');
  expect(screen.getByTestId('invalid-2').textContent).toBe('id');
  expect(screen.getByTestId('valid-count').textContent).toBe('1/3');
  expect(screen.getAllByRole('listitem').length).toBe(3);
});

