import type { Issue, Parsed, Trip, TripStop } from './contract';
import { TIMEZONES } from './contract';

const DECIMAL_ID = /^[0-9]+$/;
const ISO_LIKE = /^\d{4}-\d{2}-\d{2}T/;

const issue = (path: string, message: string): Issue => ({ path, message });

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

function parseStop(raw: unknown, path: string): { stop: TripStop | null; issues: Issue[] } {
  if (!isPlainObject(raw)) return { stop: null, issues: [issue(path, '站点必须是对象')] };
  const issues: Issue[] = [];
  const name = raw.name;
  if (typeof name !== 'string' || name.trim().length === 0) {
    issues.push(issue(path + '.name', 'name 必须是非空字符串'));
  }
  let arrival: string | undefined;
  if ('arrival' in raw) {
    if (raw.arrival === undefined) {
      // exactOptionalPropertyTypes 的运行时对应物：缺失与"显式 undefined"是两件事
      issues.push(issue(path + '.arrival', 'arrival 不得显式为 undefined'));
    } else if (typeof raw.arrival !== 'string' || !ISO_LIKE.test(raw.arrival)) {
      issues.push(issue(path + '.arrival', 'arrival 必须是 ISO 风格字符串'));
    } else {
      arrival = raw.arrival;
    }
  }
  if (issues.length) return { stop: null, issues };
  const stop: TripStop = { name: (name as string).trim() };
  if (arrival !== undefined) return { stop: { ...stop, arrival }, issues };
  return { stop, issues };
}

/** 只收集 issue、绝不抛：把外部世界的不确定性收敛成判别联合。 */
export function parseTrip(raw: unknown): Parsed<Trip> {
  const issues: Issue[] = [];
  if (!isPlainObject(raw)) return { ok: false, issues: [issue('', 'payload 必须是对象')] };

  const id = raw.id;
  if (typeof id !== 'string') {
    issues.push(issue('id', 'id 必须是字符串（长数字 ID 用 number 会掉精度）'));
  } else if (!DECIMAL_ID.test(id)) {
    issues.push(issue('id', 'id 必须是十进制数字串'));
  }

  const stops: TripStop[] = [];
  const rawStops = raw.stops;
  if (!Array.isArray(rawStops)) {
    issues.push(issue('stops', 'stops 必须是数组'));
  } else {
    // 用 for-index 而不是 for...of：稀疏数组的洞要按索引报出来
    for (let index = 0; index < rawStops.length; index += 1) {
      if (!(index in rawStops)) {
        issues.push(issue('stops[' + index + ']', '数组空洞'));
        continue;
      }
      const parsed = parseStop(rawStops[index], 'stops[' + index + ']');
      if (parsed.issues.length) issues.push(...parsed.issues);
      else stops.push(parsed.stop as TripStop);
    }
  }

  const budget = raw.budgetCents;
  if (typeof budget !== 'number' || !Number.isInteger(budget) || budget < 0) {
    issues.push(issue('budgetCents', 'budgetCents 必须是非负整数（货币不用浮点表示分）'));
  }

  const timezone = raw.timezone;
  if (typeof timezone !== 'string' || !TIMEZONES.includes(timezone)) {
    issues.push(issue('timezone', 'timezone 必须在白名单内'));
  }

  if (issues.length) return { ok: false, issues };
  return {
    ok: true,
    value: { id: id as string, stops, budgetCents: budget as number, timezone: timezone as string },
  };
}

export function TripList({ raws }: { raws: unknown[] }) {
  const parsed = raws.map((raw) => parseTrip(raw));
  const valid = parsed.filter((item) => item.ok).length;
  return (
    <>
      <ul>
        {parsed.map((item, index) =>
          item.ok ? (
            <li key={index} data-testid={'trip-' + item.value.id}>
              {item.value.stops.length + ' 站 · ' + item.value.timezone}
            </li>
          ) : (
            <li key={index} data-testid={'invalid-' + index}>
              {item.issues.map((each) => each.path).join(',')}
            </li>
          ),
        )}
      </ul>
      <span data-testid="valid-count">{valid + '/' + parsed.length}</span>
    </>
  );
}

