export function parseTrip(raw) {
  return {
    ok: true,
    value: {
      id: String(raw.id),
      stops: raw.stops ?? [],
      budgetCents: Number(raw.budgetCents),
      timezone: raw.timezone,
    },
  };
}

export function TripList({ raws }) {
  return (
    <ul>
      {raws.map((raw, index) => (
        <li key={index} data-testid={'trip-' + String(raw.id)}>
          {(raw.stops ?? []).length} 站 · {raw.timezone}
        </li>
      ))}
    </ul>
  );
}
